config.prelude:
static int atomic_cas_calls;
static int atomic_force_fail;

void test_reset_atomic(void) {
    atomic_cas_calls = 0;
    atomic_force_fail = 0;
}

void test_force_cas_failure(int force) {
    atomic_force_fail = force ? 1 : 0;
}

int test_cas_calls(void) {
    return atomic_cas_calls;
}

bool atomic_compare_exchange_u8(volatile uint8_t *addr, uint8_t expected, uint8_t desired) {
    atomic_cas_calls++;
    if (atomic_force_fail) {
        return false;
    }
    if (*addr != expected) {
        return false;
    }
    *addr = desired;
    return true;
}

visibleCases.displayInput:
spinlock_t lock;
spinlock_init(&lock);
test_reset_atomic();
bool ok = spinlock_try_lock(&lock, 42);

spinlock_t lock;
spinlock_init(&lock);
test_reset_atomic();
bool first = spinlock_try_lock(&lock, 1);
bool second = spinlock_try_lock(&lock, 2);

spinlock_t lock;
spinlock_init(&lock);
bool locked = spinlock_try_lock(&lock, 7);
bool unlocked = spinlock_unlock(&lock, 7);
bool relocked = spinlock_try_lock(&lock, 8);
